package com.vandorlabs.client;
import com.vandorlabs.blocks.ModBlocks;
import com.vandorlabs.tiles.*;
import com.vandorlabs.redstone.*;
import net.minecraft.nbt.*;
/** Actual standalone bank operations, partial overlap, detents and absolute pulse deadlines. */
public final class ScreenRowActionsLegacyChecks {
 private static final int A=73161,B=73162,C=73163;private static final net.minecraft.util.math.BlockPos POS=new net.minecraft.util.math.BlockPos(0,80,0);
 public static void main(String[] args)throws Exception{net.minecraft.init.Bootstrap.register();java.security.MessageDigest hash=java.security.MessageDigest.getInstance("SHA-256");int cases=0;for(int low:new int[]{1,5,10})for(int high:new int[]{12,15}){NonRenderingChecks.MemoryWorld world=new NonRenderingChecks.MemoryWorld(false);world.time=100;world.setBlockState(POS,ModBlocks.ANIMATED_SCREEN_SELECTOR.getDefaultState(),2);RedstoneScreenContents controls=((TileEntityAnimatedScreenSelector)world.getTileEntity(POS)).redstoneScreen(0);if(!controls.applyRowConfiguration("Bank",rows(low,high)))throw new AssertionError("Source controls setup");digest(hash,world,controls);cases++;
  controls.toggleRow(1);digest(hash,world,controls);cases++;controls.toggleRow(0);digest(hash,world,controls);cases++;world.time=107;controls.toggleRow(0);digest(hash,world,controls);cases++;controls.expirePulses(120);digest(hash,world,controls);cases++;world.time=127;controls.expirePulses(127);digest(hash,world,controls);cases++;
  for(int step=0;step<4;step++){controls.selectSegment(2,step);digest(hash,world,controls);cases++;}controls.toggleRow(1);digest(hash,world,controls);cases++;
  controls.pulseRow(0);controls.setEnabled(false);tick(world);world.time=132;controls.setEnabled(true);digest(hash,world,controls);cases++;world.time=147;tick(world);digest(hash,world,controls);cases++;
  NBTTagCompound saved=controls.writeToNBT(new NBTTagCompound());controls.onChunkUnload();digest(hash,world,controls);cases++;controls.readFromNBT(saved);controls.finishLoading();digest(hash,world,controls);cases++;controls.invalidate();
 }StringBuilder out=new StringBuilder();for(byte b:hash.digest())out.append(String.format("%02x",b&255));if(!out.toString().equals("9ed7cad76c20629b897e1bc41bdca59795932e0b28a0fcb910d87eabaf9d1c4a"))throw new AssertionError("Actual source row actions changed "+out);System.out.println("Actual Screen row actions reference PASS cases="+cases+" sha256="+out);}
 public static NBTTagList rows(int low,int high){NBTTagList rows=new NBTTagList();for(int i=0;i<3;i++){NBTTagCompound row=new NBTTagCompound();row.setString("Label",i==0?"Pulse":i==1?"Toggle":"Slider");row.setIntArray("RedstoneChannels",i==0?new int[]{A,B}:new int[]{i==1?B:C});row.setBoolean("Pulse",i==0);row.setBoolean("Slider",i==2);row.setInteger("Min",low);row.setInteger("Max",high);rows.appendTag(row);}return rows;}
 private static void tick(NonRenderingChecks.MemoryWorld world){ScreenPulseActivity.tick(new net.minecraftforge.fml.common.gameevent.TickEvent.WorldTickEvent(net.minecraftforge.fml.relauncher.Side.SERVER,net.minecraftforge.fml.common.gameevent.TickEvent.Phase.END,world));}
 private static void digest(java.security.MessageDigest hash,NonRenderingChecks.MemoryWorld world,RedstoneScreenContents controls)throws Exception{StringBuilder text=new StringBuilder(canonical(controls.writeToNBT(new NBTTagCompound())));for(int channel:new int[]{A,B,C})text.append(':').append(RedstoneChannels.level(world,POS,channel));hash.update(text.toString().getBytes("UTF-8"));}
 private static String canonical(NBTBase tag){if(tag instanceof NBTTagCompound){NBTTagCompound compound=(NBTTagCompound)tag;StringBuilder out=new StringBuilder("{");for(String key:new java.util.TreeSet<String>(compound.getKeySet()))out.append(key).append(':').append(canonical(compound.getTag(key))).append(';');return out.append('}').toString();}if(tag instanceof NBTTagList){NBTTagList list=(NBTTagList)tag;StringBuilder out=new StringBuilder("[");for(int i=0;i<list.tagCount();i++)out.append(canonical(list.get(i))).append(';');return out.append(']').toString();}return tag.toString();}
}
